import React, { useState } from 'react';
import './EditPost.css';

function EditPost({ photo, text, addEditedPost,editOpen,setEditOpen }) {
    const [pic, setPic] = useState("")
    const [editedText, setEditedText] = useState('')

    const editPost = () => {
        if (editedText===''){
            setEditedText(text);
        }
        if (pic === "") {
            setPic(photo)
            addEditedPost(editedText, pic) 
            
        }
        else{
            addEditedPost(editedText, pic) 
        }
        setEditOpen(!editOpen);
    }

    return (
<div className='EditPost'>
        <div class="card-edit">
            <div class="row">
                <div class="editStatuse">
                    <div class="editStatusetext">
                        <input value={editedText} onChange={e => setEditedText(e.currentTarget.value)} class="search" placeholder={text}
                            aria-label="Search"></input>
                    </div>
                    <div className='editStatusePic'>
                        <input class="form-control" onChange={e => setPic(e.target.files[0])} type="file" id="formFile"></input>
                    </div>
                </div>
            </div>
            <div class="editStatusButton">
                <button type="button" class="btn btn-light" onClick={() => editPost(text, pic)} >Save Edit</button>
            </div>

        </div>
        </div>

    );
}
export default EditPost;
